mapper.select:
WITH scoped AS ( SELECT e.id, e.course_id, e.applied_at, e.approved_at, e.status, c.title, u.birth_date, u.gender FROM tb_enrollments e JOIN tb_courses c ON c.id = e.course_id JOIN tb_users u ON u.id = e.user_id WHERE c.deleted_at IS NULL -- 승인·수료는 신청 뒤에만 일어나므로 기간 끝 이후 신청은 어느 집계에도 들 수 없다. AND e.applied_at < #{to}
AND c.classification_code LIKE #{prefix} || '%'
AND c.institution_id = #{institutionId}
), events AS ( SELECT AS stat_key, s.title, 1 AS applied, 0 AS approved, 0 AS completed FROM scoped s WHERE s.applied_at >= #{from} AND s.applied_at < #{to} UNION ALL SELECT , s.title, 0, 1, 0 FROM scoped s WHERE s.status = 'APPROVED' AND s.approved_at >= #{from} AND s.approved_at < #{to} UNION ALL SELECT , s.title, 0, 0, 1 FROM scoped s JOIN tb_completions cp ON cp.enrollment_id = s.id WHERE cp.status = 'COMPLETED' AND cp.completed_at >= #{from} AND cp.completed_at < #{to} ) SELECT stat_key, MAX(title) AS label, SUM(applied) AS applied, SUM(approved) AS approved, SUM(completed) AS completed FROM events GROUP BY stat_key
ORDER BY SUM(applied) DESC, stat_key LIMIT #{limit}
ORDER BY stat_key
